# protein BERT large -- batch 512, lr 1.10e-05  (grid)
# The protein batch-size grid of the 2026-11-20 directive. Generated by
# scripts/protein_batch_sweep_configs.py from the derived arm inventory; edit the
# inventory and regenerate rather than editing this file.
#
# Budget fixed in columns, not steps (section 2): 85,708,800 packed blocks of 1024
# tokens = 87,765,811,200 tokens, the same for every arm. At batch 512 that is 167,400
# steps, so the five batches cover the same data and compare at the same column.
#
# Rate = this size's 2,560 rate x sqrt(batch/2560) x 0.7 (section 3).
# Warmup 10 % of this arm's length, truncated: 16,740 of 167,400 (section 2).
#
# One GPU takes 32 columns (MEASURED, section 4) and accumulation carries the rest:
# 32 x 4 x 4 GPUs = 512.

from typing import Any, Dict, List

import torch
from transformers import DataCollatorForLanguageModeling

from molcrawl.core.paths import UNIPROT_DATASET_DIR, get_bert_output_path
from molcrawl.data.protein_sequence.utils.bert_tokenizer import create_bert_protein_tokenizer

tokenizer = create_bert_protein_tokenizer()


def preprocess_function(examples):
    """Add attention_mask for BERT compatibility."""
    if "input_ids" in examples:
        input_ids = examples["input_ids"]
        pad_id = getattr(tokenizer, "pad_token_id", None)
        pad_id = pad_id if pad_id is not None else 0
        if isinstance(input_ids[0], list):
            examples["attention_mask"] = [[1 if t != pad_id else 0 for t in seq] for seq in input_ids]
        else:
            examples["attention_mask"] = [1 if t != pad_id else 0 for t in input_ids]
    return examples


class ProteinSequenceDataCollator(DataCollatorForLanguageModeling):
    """Protein collator that renames sequence_tokens -> input_ids before masking."""

    def torch_call(self, examples: List[Dict[str, Any]]) -> Dict[str, torch.Tensor]:
        for example in examples:
            if "sequence_tokens" in example and "input_ids" not in example:
                example["input_ids"] = example.pop("sequence_tokens")
        return super().torch_call(examples)


# Mask rate 0.2, through the protein collator (section 8); not settable from main.py.
data_collator = ProteinSequenceDataCollator(tokenizer=tokenizer, mlm=True, mlm_probability=0.2)

model_size = "large"
model_path = get_bert_output_path("protein_sequence", model_size) + "-b512-lr1p1e5"
dataset_dir = UNIPROT_DATASET_DIR
max_length = 1024

max_steps = 167400
warmup_steps = 16740  # 10 % of max_steps (section 2)
learning_rate = 1.1e-05
weight_decay = 0.01
# 0.999, not main.py's 0.95: protein collapses at 0.95 (base config note). Essential.
adam_beta2 = 0.999
# Pretraining runs the whole schedule (section 8); no early stop, no collapse-floor stop.
early_stopping = False
degenerate_loss_threshold = None

log_interval = 744  # = eval_steps
save_steps = 3720
save_on_improve = True

# The judged metric and the kept checkpoint follow the same name (section 7).
judge_on = "eval_loss_mask"
metric_for_best_model = "eval_loss_mask"
save_on_improve_metric = "eval_loss_mask"
checkpoint_metric = "eval_loss_mask"

# Same masked positions at every evaluation, on every BERT arm (section 6).
fixed_eval_mask = True
eval_mask_seed = 42
# Evaluation subset: the first 10,000 valid rows (main.py EVAL_SUBSET_ROWS), not random.
# The subset seed is NOT declared here; the rows come from one constant in main.py.
per_device_eval_batch_size = 32

document_masking = True

batch_size = 32
gradient_accumulation_steps = 4
expected_global_batch = 512  # main.py stops a launch whose GPU count rebuilds another batch (section 5)

dataloader_num_workers = 4
dataloader_pin_memory = True
bf16 = True

# Parallelise the one-time attention_mask .map over the 9.5M-row train split
# (main.py applies preprocess_function at startup). Operational only: the mask is
# deterministic (1 for non-pad, 0 for pad), so num_proc changes startup time, not the
# data. The base configs leave it at 1, which is ~80 min single-process per run.
preprocess_num_proc = 16

meta_vocab_size = len(tokenizer.get_vocab())
seed = 42
